const favoriteStorageKey = 'alasas-favorites'
function readFavoriteIds(): string[] { try { const value = JSON.parse(localStorage.getItem(favoriteStorageKey) || '[]'); return Array.isArray(value) ? value.filter((id): id is string => typeof id === 'string') : [] } catch { return [] } }
function syncFavoriteIdsToAccount(ids: string[], replace = true) { if (!firebaseAuth.currentUser) return; void httpsCallable(firebaseFunctions, 'syncCustomerFavorites')({ favoriteIds: ids, replace }).catch(() => undefined) }
function toggleFavoriteId(id: string): boolean { const current = readFavoriteIds(); const next = current.includes(id) ? current.filter(item => item !== id) : [...current, id]; localStorage.setItem(favoriteStorageKey, JSON.stringify(next)); syncFavoriteIdsToAccount(next, true); window.dispatchEvent(new Event('alasas-favorites-changed')); return next.includes(id) }
function FavoriteAccountSync() { useEffect(() => onAuthStateChanged(firebaseAuth, user => { if (!user) return; const localIds = readFavoriteIds(); void httpsCallable(firebaseFunctions, 'syncCustomerFavorites')({ favoriteIds: localIds, replace: false }).then(result => { const data = result.data as { favoriteIds?: unknown }; const ids = Array.isArray(data.favoriteIds) ? data.favoriteIds.filter((id): id is string => typeof id === 'string') : localIds; localStorage.setItem(favoriteStorageKey, JSON.stringify(ids)); window.dispatchEvent(new Event('alasas-favorites-changed')) }).catch(() => undefined) }), []); return null }

type CatalogState = { products: Product[]; categories: [string, string, string][]; live: boolean; loading: boolean; error: string; publicConfig: ShopPublicConfig }
const CatalogContext = createContext<CatalogState | null>(null)
const fallbackProductImage = `${import.meta.env.BASE_URL}alasas-logo.jpg`
function mapCatalogProduct(record: FlowerProductRecord): Product {
  return {
    id: record.id,
    name: record.name,
    en: record.nameEn || record.name,
    price: record.price,
    ...(record.compareAtPrice ? { compareAtPrice: record.compareAtPrice } : {}),
    ...(record.discountPercent ? { discountPercent: record.discountPercent } : {}),
    ...(record.packaging ? { packaging: record.packaging } : {}),
    ...(record.colors?.length ? { colors: record.colors } : {}),
    ...(record.addOns?.length ? { addOns: record.addOns } : {}),
    category: record.category,
    image: record.image || record.imageUrls?.[0] || fallbackProductImage,
    ...(record.imageUrls?.length ? { imageUrls: record.imageUrls } : {}),
    description: record.description || 'منتج متاح من متجر الأساس.',
    tone: '#b7ff2a',
  }
}
function CatalogProvider({ children }: { children: React.ReactNode }) {
  const [records, setRecords] = useState<FlowerProductRecord[]>([])
  const [categoryRecords, setCategoryRecords] = useState<FlowerCategoryRecord[]>([])
  const [publicConfig, setPublicConfig] = useState<ShopPublicConfig>({ paymentMethods: {}, delivery: {}, settings: {}, homepage: {}, aiAssistant: {} })
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  useEffect(() => subscribeToShopProducts('floor-232bc', value => { setRecords(value); setLoading(false) }, reason => { setError(reason.message); setLoading(false) }), [])
  useEffect(() => subscribeToShopCategories('floor-232bc', setCategoryRecords, reason => setError(reason.message)), [])
  useEffect(() => subscribeToShopPublicConfig('floor-232bc', setPublicConfig, reason => setError(reason.message)), [])
  const liveProducts = records.map(mapCatalogProduct)
  const liveCategories: [string, string, string][] = categoryRecords.map(record => [record.name, record.description || 'اكتشف تشكيلات الأساس', record.image || 'photo-1523438885200-e635ba2c371e'])
  return <CatalogContext.Provider value={{ products: liveProducts.length ? liveProducts : products, categories: liveCategories.length ? liveCategories : categories, live: liveProducts.length > 0, loading, error, publicConfig }}>{children}</CatalogContext.Provider>
}
function useCatalog() { const value = useContext(CatalogContext); if (!value) throw new Error('useCatalog must be used inside CatalogProvider'); return value }

type CartOptions = { packaging?: string; packagingColor?: string; giftMessage?: string; addOns?: string[] }
type CartLine = { productId: string; quantity: number } & CartOptions
type CartState = {
  items: CartLine[]
  count: number
  add: (productId: string, quantity?: number, options?: CartOptions) => void
  setQuantity: (productId: string, quantity: number) => void
  remove: (productId: string) => void
  clear: () => void
}
function useCart(): CartState {
  const [items, setItems] = useState<CartLine[]>(() => {
    try {
      const stored = JSON.parse(localStorage.getItem('alasas-cart') || '[]')
      return Array.isArray(stored) ? stored.filter(item => typeof item?.productId === 'string' && Number.isInteger(item.quantity) && item.quantity > 0).map(item => ({ productId: item.productId, quantity: item.quantity, ...(typeof item.packaging === 'string' ? { packaging: item.packaging } : {}), ...(typeof item.packagingColor === 'string' ? { packagingColor: item.packagingColor } : {}), ...(typeof item.giftMessage === 'string' ? { giftMessage: item.giftMessage } : {}), ...(Array.isArray(item.addOns) ? { addOns: item.addOns.filter((value: unknown): value is string => typeof value === 'string') } : {}) })) : []
    } catch { return [] }
  })
  const persist = (next: CartLine[]) => { setItems(next); localStorage.setItem('alasas-cart', JSON.stringify(next)) }
  const add = (productId: string, quantity = 1, options: CartOptions = {}) => {
    const current = items.find(item => item.productId === productId)
    const next = current ? items.map(item => item.productId === productId ? { ...item, ...options, quantity: item.quantity + quantity } : item) : [...items, { productId, quantity, ...options }]
    persist(next)
  }
  const setQuantity = (productId: string, quantity: number) => persist(quantity > 0 ? items.map(item => item.productId === productId ? { ...item, quantity } : item) : items.filter(item => item.productId !== productId))
  const remove = (productId: string) => persist(items.filter(item => item.productId !== productId))
  const clear = () => persist([])
  return { items, count: items.reduce((sum, item) => sum + item.quantity, 0), add, setQuantity, remove, clear }
}

function App() {
  const cart = useCart(); const location = useLocation(); const [menu, setMenu] = useState(false); const [toast, setToast] = useState('')
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2600) }
  if (location.pathname.startsWith('/admin')) return <Routes><Route path="/admin/*" element={<AdminGate><AdminApp /></AdminGate>} /></Routes>
  return <CatalogProvider><div className="app-shell">
    <FavoriteAccountSync />
    <Announcement />
    <Header menu={menu} setMenu={setMenu} cartCount={cart.count} />
    <AnimatePresence>{toast && <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="toast"><Check size={16} /> {toast}</motion.div>}</AnimatePresence>
    {location.pathname === '/checkout' && <CheckoutReview cart={cart} />}
    <Routes>
      <Route path="/" element={<Home onAdd={(id) => { cart.add(id); notify('تمت إضافة الباقة إلى السلة') }} />} />
      <Route path="/shop" element={<Shop onAdd={(id) => { cart.add(id); notify('تمت إضافة المنتج إلى السلة') }} />} />
      <Route path="/product/:slug" element={<ProductPage onAdd={(id, quantity, options) => { cart.add(id, quantity, options); notify('تمت إضافة المنتج إلى السلة') }} />} />
      <Route path="/design-your-bouquet" element={<Designer onAdd={() => notify('التصميم التوضيحي لا يُضاف كمنتج حتى يتم اعتماده من المتجر')} />} />
      <Route path="/ai-bouquet-designer" element={<AIDesignerConnected onAdd={() => notify('المعاينة التوضيحية لا تُضاف كمنتج حتى يتم اعتمادها من المتجر')} />} />
      <Route path="/cart" element={<Cart cart={cart} />} />
      <Route path="/checkout" element={<CheckoutConnected cart={cart} />} />
      <Route path="/track-order" element={<TrackOrder />} />
      <Route path="/favorites" element={<Favorites />} />
      <Route path="/account" element={<Account />} />
      <Route path="*" element={<NotFound />} />
    </Routes>
    <ChatFab />
    <Footer />
  </div></CatalogProvider>
}

function Announcement() { const { publicConfig } = useCatalog(); const settings = publicConfig.settings; const closed = settings.acceptingOrders === false || settings.temporaryClosed === true; const announcement = typeof settings.announcement === 'string' && settings.announcement.trim() ? settings.announcement : closed ? 'المتجر مغلق مؤقتاً لاستقبال الطلبات' : 'هديتك المميزة تبدأ من هنا — توصيل داخل بغداد'; return <div className="announcement"><span><Zap size={14} fill="currentColor" /> {announcement}</span><span className="desktop-only">{closed ? 'سنعود قريباً' : 'الدفع عند الاستلام متاح حسب إعدادات المتجر'}</span></div> }
function Header({ menu, setMenu, cartCount }: { menu: boolean; setMenu: (v: boolean) => void; cartCount: number }) {
  const { publicConfig } = useCatalog(); const settings = publicConfig.settings; const storeName = typeof settings.storeName === 'string' && settings.storeName.trim() ? settings.storeName : 'الأساس'; const storeLogo = configuredImage(settings.logoUrl, logo)
  return <header className="header"><div className="header-inner">
    <button className="mobile-menu icon-btn" onClick={() => setMenu(!menu)} aria-label="فتح القائمة">{menu ? <X /> : <Menu />}</button>
    <Link to="/" className="brand"><img src={storeLogo} alt={`${storeName} AL ASAS`} /><span><b>{storeName}</b><small>من الأساس تبدأ الفكرة</small></span></Link>
    <nav className={`main-nav ${menu ? 'open' : ''}`}>
      <NavLink to="/" end>الرئيسية</NavLink><NavLink to="/shop">تسوّق</NavLink><NavLink to="/design-your-bouquet">صمّم باقتك</NavLink><NavLink to="/shop?category=هدايا التخرج">المناسبات</NavLink><NavLink to="/ai-bouquet-designer" className="nav-ai"><Sparkles size={15} /> مساعد الباقة</NavLink>
    </nav>
    <div className="header-actions"><button className="icon-btn desktop-only" aria-label="بحث"><Search /></button><Link to="/favorites" className="icon-btn desktop-only" aria-label="المفضلة"><Heart /></Link><Link to="/account" className="icon-btn desktop-only" aria-label="الحساب"><CircleUserRound /></Link><Link to="/cart" className="cart-btn"><ShoppingBag size={19} /><span>السلة</span>{cartCount > 0 && <em>{cartCount}</em>}</Link></div>
  </div></header>
}

